<script setup>
import{ref,computed}from'vue';import{Plus,Search,Pencil,Trash2}from'lucide-vue-next';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import{state,persist}from'../data/store';const q=ref(''),show=ref(false),editId=ref(null),form=ref({name:'',cnpj:'',email:'',phone:''});const filtered=computed(()=>state.suppliers.filter(s=>Object.values(s).join(' ').toLowerCase().includes(q.value.toLowerCase())));function open(s=null){editId.value=s?.id??null;form.value=s?{...s}:{name:'',cnpj:'',email:'',phone:''};show.value=true}function save(){if(!form.value.name)return;if(editId.value)Object.assign(state.suppliers.find(s=>s.id===editId.value),form.value);else state.suppliers.push({...form.value,id:Date.now(),active:true});persist();show.value=false}function remove(s){if(confirm(`Excluir ${s.name}?`)){state.suppliers.splice(state.suppliers.indexOf(s),1);persist()}}
</script><template><PageHeader title="Fornecedores" subtitle="Gerencie os fornecedores cadastrados."><button class="btn btn-primary" @click="open()"><Plus :size="18"/>Novo fornecedor</button></PageHeader><section class="panel"><div class="toolbar"><div class="search"><Search :size="18"/><input v-model="q" placeholder="Buscar fornecedor..."/></div></div><div class="table-wrap"><table><thead><tr><th>Fornecedor</th><th>CNPJ</th><th>E-mail</th><th>Telefone</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="s in filtered" :key="s.id"><td><b>{{s.name}}</b></td><td>{{s.cnpj}}</td><td>{{s.email}}</td><td>{{s.phone}}</td><td><span class="badge badge-success">Ativo</span></td><td class="actions"><button class="icon-btn" @click="open(s)"><Pencil :size="17"/></button><button class="icon-btn danger-text" @click="remove(s)"><Trash2 :size="17"/></button></td></tr></tbody></table></div></section><Modal v-if="show" :title="editId?'Editar fornecedor':'Cadastrar fornecedor'" @close="show=false"><form class="form-grid" @submit.prevent="save"><div class="field full"><label>Nome</label><input v-model="form.name" required/></div><div class="field"><label>CNPJ</label><input v-model="form.cnpj"/></div><div class="field"><label>Telefone</label><input v-model="form.phone"/></div><div class="field full"><label>E-mail</label><input v-model="form.email" type="email"/></div><div class="modal-actions full"><button type="button" class="btn btn-secondary" @click="show=false">Cancelar</button><button class="btn btn-primary">Salvar fornecedor</button></div></form></Modal></template>
